draw((20,-2)--(36,-2));
draw((18,-4)--(36,-4));
draw((20,-2.5)--(20,-1.5));
draw((36,-2.5)--(36,-1.5));
draw((18,-3.5)--(18,-4.5));
draw((36,-3.5)--(36,-4.5));
