label("$C$", C, SE);
label("$P$", P, NE);
label("$13$", (A + B)/2, NW);
label("$14$", (B + C)/2, S);
label("$15$", (A + C)/2, NE);

label("$x$", (A + P)/2, W);
label("$y$", (B + P)/2, NW);
label("$z$", (C + P)/2, NE);
