question:
In the diagram, what is the perimeter of polygon $PQRST$? [asy]

import olympiad;

size(6cm); // ADJUST

pair p = (0, 6);
pair q = (3, 6);

pair r = (3, 3);
pair t = (0, 0);
pair s = (7, 0);

