A = (0,0);
B = (8,0);
D = (-4,7);
C = (13,7);
F = intersectionpoint(D -- (A + 3*(A-D)), C -- (B + 3*(B-C)));
draw(A--F--C--D--A--B);
label("$A$",A,W);
label("$B$",B,E);
label("$E$",F,S);
label("$D$",D,NW);
label("$C$",C,NE);
